import { invitations, overview as initialOverview } from './data.mjs';
import { mountInvitationList } from './invitation-list.mjs';
import { mountInvitationForm } from './invitation-form.mjs';
import { mountOverview } from './overview.mjs';

const list = mountInvitationList(document.querySelector('[aria-label="Invitations"]'), invitations);
