import { test, expect } from '@playwright/test';
const rows = page => page.getByRole('list', { name: 'Invitations' }).locator('[data-invite-id]');
const confirmation = page => page.getByRole('status').filter({ hasText: /Invitation sent/ });
const order = page => rows(page).evaluateAll(nodes => nodes.map(node => node.dataset.inviteId));
function deferred() {
  let resolve;
  const promise = new Promise(done => { resolve = done; });
  return { promise, resolve };
}
function accepted(email, id = 'new-1') {
  return { invitation: { id, email, state: 'pending' }, receipt: { id: `receipt-${id}`, acceptedAt: 1730000000000 } };
}
async function deliver(page, route, response) {
  const finished = page.waitForEvent('requestfinished', { predicate: request => request === route.request() });
  await route.fulfill(response);
  await finished;
  // Observe the settled consumer after fetch completion and the next render opportunity.
  await page.evaluate(() => new Promise(resolve => requestAnimationFrame(resolve)));
}
test.beforeEach(async ({ page }) => {
  await page.route('**/api/overview', route => route.fulfill({ json: { pending: 5 } }));
  await page.route('**/api/invitations', route => {
    const { email } = route.request().postDataJSON();
    return route.fulfill({ json: { invitation: { id: 'new-1', email, state: 'pending' }, receipt: { id: 'receipt-1', acceptedAt: 1730000000000 } } });
  });
});
test('a sent invitation is shown with accessible confirmation and refreshed overview', async ({ page }) => {
  await page.goto('/'); await page.getByRole('textbox', { name: 'Email', exact: true }).fill('ada@example.test');
  await page.getByRole('button', { name: 'Send invitation', exact: true }).click();
  await expect(page.getByRole('status').filter({ hasText: /sent|accepted/i }).first()).toContainText(/sent|accepted/i);
  await expect(page.getByRole('status').filter({ hasText: /sent|accepted/i }).first()).toContainText('ada@example.test');
  await expect(rows(page)).toHaveCount(5); await expect(page.getByTestId('overview')).toContainText('5');
  await expect(confirmation(page)).toContainText('receipt-1');
  await expect(page.getByRole('textbox', { name: 'Email', exact: true })).toHaveValue('');
});
test('list buttons change display order without calling the service', async ({ page }) => {
  const serviceRequests = []; page.on('request', request => { if (request.url().includes('/api/')) serviceRequests.push(request.url()); });
  await page.goto('/'); await page.locator('[data-invite-id="mia"]').getByRole('button', { name: 'Move later', exact: true }).click();
  expect(await rows(page).evaluateAll(nodes => nodes.map(node => node.dataset.inviteId))).toEqual(['tom', 'mia', 'zoe', 'lee']);
  expect(serviceRequests).toEqual([]);
});
test('overview can be refreshed while an independent note stays intact', async ({ page }) => {
  await page.goto('/'); await page.getByRole('textbox', { name: 'Team note', exact: true }).fill('Ask about timezone');
  await page.getByRole('button', { name: 'Refresh overview', exact: true }).click();
  await expect(page.getByTestId('overview')).toContainText('5');
  await expect(page.getByRole('textbox', { name: 'Team note', exact: true })).toHaveValue('Ask about timezone');
});

test('accepted send and receipt survive delayed and failed overview, with read-only recovery', async ({ page }) => {
  const reads = [];
  let sends = 0;
  await page.route('**/api/overview', route => { reads.push(route); });
  await page.route('**/api/invitations', route => {
    sends += 1;
    return route.fulfill({ json: accepted('ada@example.test') });
  });
  await page.goto('/');
  await page.getByRole('textbox', { name: 'Email', exact: true }).fill('Ada@example.test');
  await page.getByRole('button', { name: 'Send invitation', exact: true }).click();
  await expect.poll(() => reads.length).toBe(1);
  await expect(confirmation(page)).toContainText('ada@example.test');
  await expect(confirmation(page)).toContainText('receipt-new-1');
  await expect(rows(page)).toHaveCount(5);
  await expect(page.getByTestId('overview')).toHaveText('Pending: 4');
  await expect(page.getByRole('button', { name: 'Send invitation', exact: true })).toBeEnabled();

  await deliver(page, reads[0], { status: 503, body: 'Unavailable' });
  await expect(page.getByRole('alert').filter({ hasText: /Overview unavailable/ })).toBeVisible();
  await expect(page.getByRole('alert').filter({ hasText: /Invitation could not be sent/ })).toHaveCount(0);
  await expect(confirmation(page)).toContainText('receipt-new-1');
  await expect(rows(page)).toHaveCount(5);
  await expect(page.getByTestId('overview')).toHaveText('Pending: 4');

  await page.getByRole('button', { name: 'Refresh overview', exact: true }).click();
  await expect.poll(() => reads.length).toBe(2);
  await deliver(page, reads[1], { json: { pending: 5 } });
  await expect(page.getByTestId('overview')).toHaveText('Pending: 5');
  await expect(page.getByRole('alert').filter({ hasText: /Overview unavailable/ })).toHaveCount(0);
  await expect(confirmation(page)).toContainText('receipt-new-1');
  expect(sends).toBe(1);
});

test('a rejected send preserves its draft and error through overview refresh, then permits an edited retry', async ({ page }) => {
  const submitted = [];
  await page.route('**/api/invitations', route => {
    const { email } = route.request().postDataJSON();
    submitted.push(email);
    return submitted.length === 1
      ? route.fulfill({ status: 503, body: 'Unavailable' })
      : route.fulfill({ json: accepted(email) });
  });
  await page.goto('/');
  const email = page.getByRole('textbox', { name: 'Email', exact: true });
  const send = page.getByRole('button', { name: 'Send invitation', exact: true });
  await email.fill('first@example.test');
  await send.click();
  const failure = page.getByRole('alert').filter({ hasText: /Invitation could not be sent/ });
  await expect(failure).toBeVisible();
  await expect(email).toHaveValue('first@example.test');
  await expect(send).toBeEnabled();
  await expect(rows(page)).toHaveCount(4);
  await page.getByRole('button', { name: 'Refresh overview', exact: true }).click();
  await expect(page.getByTestId('overview')).toHaveText('Pending: 5');
  await expect(failure).toBeVisible();

  await email.fill('second@example.test');
  await send.click();
  await expect(confirmation(page)).toContainText('second@example.test');
  await expect(failure).toHaveCount(0);
  await expect(rows(page)).toHaveCount(5);
  expect(submitted).toEqual(['first@example.test', 'second@example.test']);
});

test('one pending submission sends once while list actions and selected note editing remain usable', async ({ page }) => {
  const request = deferred();
  const release = deferred();
  let sends = 0;
  await page.route('**/api/invitations', async route => {
    sends += 1;
    request.resolve(route.request().postDataJSON());
    await release.promise;
    await route.fulfill({ json: accepted('ada@example.test') });
  });
  await page.goto('/');
  const email = page.getByRole('textbox', { name: 'Email', exact: true });
  const note = page.getByRole('textbox', { name: 'Team note', exact: true });
  const send = page.getByRole('button', { name: 'Send invitation', exact: true });
  await email.fill('ada@example.test');
  await email.press('Enter');
  expect(await request.promise).toEqual({ email: 'ada@example.test' });
  await expect(send).toBeDisabled();
  await expect(email).toBeFocused();
  await page.keyboard.press('Enter');
  await page.keyboard.press('Enter');
  await page.locator('[data-invite-id="mia"]').getByRole('button', { name: 'Move later', exact: true }).click();
  expect(await order(page)).toEqual(['tom', 'mia', 'zoe', 'lee']);

  await note.fill('Plan launch today');
  for (let i = 0; i < 6; i++) await page.keyboard.press('ArrowLeft');
  for (let i = 0; i < 6; i++) await page.keyboard.press('Shift+ArrowLeft');
  await expect(note).toBeFocused();
  expect(await note.evaluate(node => [node.selectionStart, node.selectionEnd])).toEqual([5, 11]);
  release.resolve();
  await expect(confirmation(page)).toContainText('receipt-new-1');
  await expect(page.getByTestId('overview')).toHaveText('Pending: 5');
  await expect(note).toBeFocused();
  expect(await note.evaluate(node => [node.selectionStart, node.selectionEnd])).toEqual([5, 11]);
  await page.keyboard.type('review');
  await expect(note).toHaveValue('Plan review today');
  expect(await order(page)).toEqual(['tom', 'mia', 'zoe', 'lee', 'new-1']);
  expect(sends).toBe(1);
});

for (const returnsToSubmitted of [false, true]) {
  test(`pending send preserves ${returnsToSubmitted ? 'A → B → A' : 'a different'} Email edit without taking focus`, async ({ page }) => {
    const request = deferred();
    const release = deferred();
    await page.route('**/api/invitations', async route => {
      request.resolve();
      await release.promise;
      await route.fulfill({ json: accepted('ada@example.test') });
    });
    await page.goto('/');
    const email = page.getByRole('textbox', { name: 'Email', exact: true });
    await email.fill('ada@example.test');
    await email.press('Enter');
    await request.promise;
    await email.fill('next@example.test');
    if (returnsToSubmitted) await email.fill('ada@example.test');
    release.resolve();
    await expect(confirmation(page)).toContainText('ada@example.test');
    await expect(page.getByTestId('overview')).toHaveText('Pending: 5');
    await expect(email).toHaveValue(returnsToSubmitted ? 'ada@example.test' : 'next@example.test');
    await expect(email).toBeFocused();
  });
}

for (const [id, name, orders] of [
  ['mia', 'Move later', [['tom', 'mia', 'zoe', 'lee'], ['tom', 'zoe', 'mia', 'lee'], ['tom', 'zoe', 'lee', 'mia']]],
  ['lee', 'Move earlier', [['mia', 'tom', 'lee', 'zoe'], ['mia', 'lee', 'tom', 'zoe'], ['lee', 'mia', 'tom', 'zoe']]],
]) {
  test(`${name} keeps pointer and consecutive keyboard activation on ${id}`, async ({ page }) => {
    const requests = [];
    page.on('request', request => { if (request.url().includes('/api/')) requests.push(request.url()); });
    await page.goto('/');
    const button = page.locator(`[data-invite-id="${id}"]`).getByRole('button', { name, exact: true });
    await button.click();
    expect(await order(page)).toEqual(orders[0]);
    await expect(button).toBeFocused();
    await page.keyboard.press('Enter');
    expect(await order(page)).toEqual(orders[1]);
    await expect(button).toBeFocused();
    await page.keyboard.press('Space');
    expect(await order(page)).toEqual(orders[2]);
    await expect(button).toBeFocused();
    await page.keyboard.press('Enter');
    expect(await order(page)).toEqual(orders[2]);
    await expect(button).toBeFocused();
    expect(requests).toEqual([]);
  });
}

for (const oldReadFails of [false, true]) {
  test(`older overview ${oldReadFails ? 'failure' : 'success'} cannot replace the newer post-send overview`, async ({ page }) => {
    const reads = [];
    await page.route('**/api/overview', route => { reads.push(route); });
    await page.goto('/');
    await page.getByRole('button', { name: 'Refresh overview', exact: true }).click();
    await expect.poll(() => reads.length).toBe(1);
    await page.getByRole('textbox', { name: 'Email', exact: true }).fill('ada@example.test');
    await page.getByRole('button', { name: 'Send invitation', exact: true }).click();
    await expect.poll(() => reads.length).toBe(2);
    await deliver(page, reads[1], { json: { pending: 6 } });
    await expect(page.getByTestId('overview')).toHaveText('Pending: 6');
    await deliver(page, reads[0], oldReadFails ? { status: 503, body: 'Unavailable' } : { json: { pending: 99 } });
    await expect(page.getByTestId('overview')).toHaveText('Pending: 6');
    await expect(page.getByRole('alert').filter({ hasText: /Overview unavailable/ })).toHaveCount(0);
    await expect(confirmation(page)).toContainText('receipt-1');
  });
