test('an old overview completion cannot clear a newer loading state or publish its value', async ({ page }) => {
  const reads = [];
  await page.route('**/api/overview', route => { reads.push(route); });
  await page.goto('/');
  const refresh = page.getByRole('button', { name: 'Refresh overview', exact: true });
  await refresh.click();
  await expect.poll(() => reads.length).toBe(1);
  await refresh.click();
  await expect.poll(() => reads.length).toBe(2);
  await deliver(page, reads[0], { json: { pending: 99 } });
  await expect(page.getByTestId('overview')).toHaveText('Pending: 4');
  await expect(page.getByRole('status').filter({ hasText: 'Refreshing overview…' })).toBeVisible();
  await deliver(page, reads[1], { status: 503, body: 'Unavailable' });
  await expect(page.getByTestId('overview')).toHaveText('Pending: 4');
  await expect(page.getByRole('status').filter({ hasText: 'Refreshing overview…' })).toHaveCount(0);
  await expect(page.getByRole('alert').filter({ hasText: /Overview unavailable/ })).toBeVisible();
